Since the `mc.h` header is not available, I'll implement wide bus coalescing directly using `ap_uint<512>` from `ap_int.h`, packing/unpacking 8 doubles per 512-bit word, while keeping all existing double-buffering, pipeline, and unroll optimizations.

```cpp
#include "mvt.h"
#include <string.h>
#include <ap_int.h>

#ifndef TILE
#define TILE 32
#endif

// 512-bit wide bus: 8 doubles per word (8 * 64 = 512)
#define WIDE_BUS_WIDTH 512
#define DOUBLES_PER_WORD 8
typedef ap_uint<WIDE_BUS_WIDTH> wide_bus_t;

// Helper: read 'count' doubles from wide bus pointer into local array
static void wide_read_double(double* dst, const wide_bus_t* src, int byte_offset, int count) {
#pragma HLS INLINE
    int word_start = byte_offset / (DOUBLES_PER_WORD * 8);
    int elem_start = (byte_offset / 8) % DOUBLES_PER_WORD;
    int idx = 0;
    for (int w = word_start; idx < count; w++) {
#pragma HLS PIPELINE II=1
        wide_bus_t word = src[w];
        for (int d = (w == word_start ? elem_start : 0); d < DOUBLES_PER_WORD && idx < count; d++) {
#pragma HLS UNROLL
            ap_uint<64> bits = word.range(d*64+63, d*64);
            double val;
            memcpy(&val, &bits, 8);
            dst[idx++] = val;
        }
    }
}

// Helper: write 'count' doubles from local array to wide bus pointer
static void wide_write_double(wide_bus_t* dst, int byte_offset, const double* src, int count) {
#pragma HLS INLINE
    int word_start = byte_offset / (DOUBLES_PER_WORD * 8);
    int elem_start = (byte_offset / 8) % DOUBLES_PER_WORD;
    int idx = 0;
    for (int w = word_start; idx < count; w++) {
#pragma HLS PIPELINE II=1
        wide_bus_t word = dst[w];
        for (int d = (w == word_start ? elem_start : 0); d < DOUBLES_PER_WORD && idx < count; d++) {
#pragma HLS UNROLL
            ap_uint<64> bits;
            memcpy(&bits, &src[idx++], 8);
            word.range(d*64+63, d*64) = bits;
        }
        dst[w] = word;
    }
}

